create or replace function public.svc_qilt_upsert_mappings(p_source_id uuid,p_rows jsonb) returns jsonb language plpgsql security definer set search_path to 'pipeline','catalogue','ref','public','extensions' as $function$ declare r jsonb; v_seen int:=0; v_changed int:=0; v_rc int; begin if jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows)>3000 then raise exception 'bounded mapping array required'; end if; for r in select value from jsonb_array_elements(p_rows) loop if nullif(r->>'provider_id','') is not null and not exists(select 1 from catalogue.providers p join ref.countries c on c.id=p.country_id where p.id=(r->>'provider_id')::uuid and c.iso_alpha2='AU') then raise exception 'mapping target must be existing AU CRICOS provider'; end if; insert into pipeline.source_provider_mappings(source_id,source_entity_key,source_entity_name,provider_id,match_method,match_confidence,status,verified_at,metadata) values(p_source_id,r->>'source_entity_key',r->>'source_entity_name',nullif(r->>'provider_id','')::uuid,coalesce(nullif(r->>'match_method',''),'unmatched'),nullif(r->>'match_confidence','')::numeric,coalesce(nullif(r->>'status',''),'unmatched'),nullif(r->>'verified_at','')::timestamptz,coalesce(r->'metadata','{}'::jsonb)) on conflict(source_id,source_entity_key) do update set source_entity_name=excluded.source_entity_name,provider_id=excluded.provider_id,match_method=excluded.match_method,match_confidence=excluded.match_confidence,status=excluded.status,verified_at=case when pipeline.source_provider_mappings.provider_id is not distinct from excluded.provider_id and pipeline.source_provider_mappings.status=excluded.status then pipeline.source_provider_mappings.verified_at else excluded.verified_at end,metadata=excluded.metadata,updated_at=now() where (pipeline.source_provider_mappings.source_entity_name,pipeline.source_provider_mappings.provider_id,pipeline.source_provider_mappings.match_method,pipeline.source_provider_mappings.match_confidence,pipeline.source_provider_mappings.status,pipeline.source_provider_mappings.metadata) is distinct from (excluded.source_entity_name,excluded.provider_id,excluded.match_method,excluded.match_confidence,excluded.status,excluded.metadata); get diagnostics v_rc=row_count; v_seen:=v_seen+1; v_changed:=v_changed+v_rc; end loop; return jsonb_build_object('seen',v_seen,'changed',v_changed); end $function$; revoke all on function public.svc_qilt_upsert_mappings(uuid,jsonb) from public,anon,authenticated; grant execute on function public.svc_qilt_upsert_mappings(uuid,jsonb) to service_role;
